#include <iostream>
#include <string>
#include <cctype>
using namespace std;

int main() {
    string a = "apple";
    string b = "banana";
    if (a < b) {
        cout << a << " comes before " << b << endl;
    }
    cout << "compare is negative: " << (a.compare(b) < 0) << endl;
    string x = "Zebra";
    string y = "apple";
    if (x < y) {
        cout << "Zebra < apple is true" << endl;
    }

    string line;
    getline(cin, line);
    int letters = 0;
    int digits = 0;
    string num = "";
    string up = line;
    for (size_t i = 0; i < line.length(); i++) {
        if (isalpha(line[i])) {
            letters++;
        }
        if (isdigit(line[i])) {
            digits++;
            num += line[i];
        }
        up[i] = toupper(line[i]);
    }
    cout << "Letters: " << letters << endl;
    cout << "Digits: " << digits << endl;
    cout << "Upper: " << up << endl;
    int value = stoi(num);
    cout << "Number found: " << value << ", plus one: " << to_string(value + 1) << endl;
    return 0;
}

#include <iostream>
#include <string>
#include <cctype>
using namespace std;

int main() {
    string w;
    cin >> w;
    int vowels = 0;
    string rev = "";
    string lower = "";
    string lowerRev = "";
    for (size_t i = 0; i < w.length(); i++) {
        char c = tolower(w[i]);
        if (c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u') {
            vowels++;
        }
        rev = w[i] + rev;
        lower = lower + c;
        lowerRev = c + lowerRev;
    }
    cout << "Vowels: " << vowels << endl;
    cout << "Reversed: " << rev << endl;
    if (lower == lowerRev) {
        cout << w << " is a palindrome (ignoring case)" << endl;
    } else {
        cout << w << " is not a palindrome" << endl;
    }
    return 0;
}

